package com.infosys.carbonfootprint.controller;
import com.infosys.carbonfootprint.dto.*; import com.infosys.carbonfootprint.entity.*; import com.infosys.carbonfootprint.exception.ResourceNotFoundException; import com.infosys.carbonfootprint.repository.*; import com.infosys.carbonfootprint.response.ApiResponse; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import jakarta.validation.Valid; import java.util.*;
@RestController @RequestMapping("/api/v1/admin/emission-limits") @PreAuthorize("hasRole('ADMIN')") public class EmissionLimitController { private final EmissionLimitRepository limits; private final CategoryRepository categories; public EmissionLimitController(EmissionLimitRepository l,CategoryRepository c){limits=l;categories=c;} private EmissionLimitDto dto(EmissionLimit x){return EmissionLimitDto.builder().id(x.getId()).categoryId(x.getCategory().getCategoryId()).categoryName(x.getCategory().getCategoryName()).monthlyLimit(x.getMonthlyLimit()).unit(x.getUnit()).active(x.isActive()).build();} @GetMapping public ApiResponse<List<EmissionLimitDto>> all(){return ApiResponse.success("Limits fetched",limits.findAll().stream().map(this::dto).toList());} @PostMapping public ApiResponse<EmissionLimitDto> save(@Valid @RequestBody EmissionLimitRequest r){EmissionLimit x=limits.findByCategoryCategoryIdAndActiveTrue(r.getCategoryId()).orElse(EmissionLimit.builder().category(categories.findById(r.getCategoryId()).orElseThrow(()->new ResourceNotFoundException("Category","id",r.getCategoryId()))).build());x.setMonthlyLimit(r.getMonthlyLimit());x.setActive(r.getActive()==null||r.getActive());return ApiResponse.success("Limit saved",dto(limits.save(x)));} @DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){limits.delete(limits.findById(id).orElseThrow(()->new ResourceNotFoundException("Emission limit","id",id)));return ApiResponse.success("Limit deleted");} }